#include <stdio.h>
/*
 * ex02：中断 / 异常的来源判定与「返回到哪」
 * 为什么：408 最爱考「下列事件属于外中断还是内中断、返回时回到哪条指令」。
 *        关键判据只有两个：① 是否由当前指令引起；② 是否可恢复。
 *   外中断(中断)：与当前指令无关，返回到「下一条指令」
 *   内中断(异常)：由当前指令引起
 *       - 故障 fault：可恢复，返回到「当前这条指令」重新执行
 *       - 自陷 trap ：主动陷入，返回到「下一条指令」
 *       - 终止 abort：不可恢复，进程被杀死，不返回
 */
typedef struct {
    const char *event;   /* 事件名 */
    int from_outside;    /* 1 = 来自 CPU 外部 */
    const char *kind;    /* "irq" / "fault" / "trap" / "abort" */
} Ev;

int main(void) {
    Ev evs[] = {
        {"时钟中断",        1, "irq"},
        {"键盘敲击",        1, "irq"},
        {"网卡收包",        1, "irq"},
        {"缺页(页不在内存)", 0, "fault"},
        {"除数为 0",        0, "fault"},
        {"系统调用 int 0x80", 0, "trap"},
        {"断点 int3",       0, "trap"},
        {"内存校验错",      0, "abort"}
    };
    int n = (int)(sizeof(evs) / sizeof(evs[0]));

    printf("%-22s %-10s %-12s %s\n", "事件", "分类", "子类", "返回地址");
    printf("------------------------------------------------------------------\n");
    for (int i = 0; i < n; i++) {
        const char *category, *sub, *ret;
        if (evs[i].from_outside) {
            category = "外中断";
            sub = "可屏蔽/不可屏蔽";
            ret = "下一条指令";
        } else {
            category = "内中断(异常)";
            if (evs[i].kind[0] == 'f') { sub = "故障 fault"; ret = "当前指令(重执行)"; }
            else if (evs[i].kind[0] == 't') { sub = "自陷 trap"; ret = "下一条指令"; }
            else { sub = "终止 abort"; ret = "不返回(杀进程)"; }
        }
        printf("%-22s %-10s %-12s %s\n", evs[i].event, category, sub, ret);
    }
    printf("\n记忆口诀：外部看「来没来」，内部看「能不能修」——能修回当前，主动回下条，修不了就终止。\n");
    return 0;
}
